#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    struct DSU {
        vector<int> parent, sz;

        DSU(int n) {
            parent.resize(n);
            sz.assign(n, 1);
            iota(parent.begin(), parent.end(), 0);
        }

        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }

        void unite(int a, int b) {
            int ra = find(a), rb = find(b);
            if (ra == rb) return;
            if (sz[ra] < sz[rb]) swap(ra, rb);
            parent[rb] = ra;
            sz[ra] += sz[rb];
        }

        int size(int x) {
            return sz[find(x)];
        }
    };

    vector<int> hitBricks(vector<vector<int>>& grid, vector<vector<int>>& hits) {
        int m = grid.size();
        int n = grid[0].size();
        int total = m * n;
        int roof = total;

        vector<vector<int>> state = grid;

        for (auto& hit : hits) {
            int r = hit[0], c = hit[1];
            state[r][c] = 0;
        }

        DSU dsu(total + 1);

        auto id = [&](int r, int c) {
            return r * n + c;
        };

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (state[r][c] == 0) continue;

                if (r == 0) {
                    dsu.unite(id(r, c), roof);
                }

                if (r > 0 && state[r - 1][c] == 1) {
                    dsu.unite(id(r, c), id(r - 1, c));
                }

                if (c > 0 && state[r][c - 1] == 1) {
                    dsu.unite(id(r, c), id(r, c - 1));
                }
            }
        }

        vector<int> result(hits.size(), 0);
        vector<int> dr = {-1, 1, 0, 0};
        vector<int> dc = {0, 0, -1, 1};

        for (int i = hits.size() - 1; i >= 0; i--) {
            int r = hits[i][0];
            int c = hits[i][1];

            if (grid[r][c] == 0) {
                result[i] = 0;
                continue;
            }

            int before = dsu.size(roof);

            state[r][c] = 1;
            int cur = id(r, c);

            if (r == 0) {
                dsu.unite(cur, roof);
            }

            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k];
                int nc = c + dc[k];

                if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
                if (state[nr][nc] == 0) continue;

                dsu.unite(cur, id(nr, nc));
            }

            int after = dsu.size(roof);
            result[i] = max(0, after - before - 1);
        }

        return result;
    }
};
```

