class Solution {
public:
    int numFactoredBinaryTrees(vector<int>& arr) {
        const long long MOD = 1000000007;
        sort(arr.begin(), arr.end());

        int n = arr.size();
        unordered_map<int, int> index;
        for (int i = 0; i < n; i++) {
            index[arr[i]] = i;
        }

        vector<long long> dp(n, 1);

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (arr[i] % arr[j] == 0) {
                    int other = arr[i] / arr[j];
                    if (index.count(other)) {
                        int k = index[other];
                        dp[i] = (dp[i] + dp[j] * dp[k]) % MOD;
                    }
                }
            }
        }

        long long ans = 0;
        for (long long count : dp) {
            ans = (ans + count) % MOD;
        }

        return (int)ans;
    }
};
```

