class Solution {
public:
    int clumsy(int n) {
        std::vector<int> st;
        st.push_back(n);

        int op = 0;
        for (int x = n - 1; x >= 1; --x) {
            if (op == 0) {
                st.back() *= x;
            } else if (op == 1) {
                st.back() /= x;
            } else if (op == 2) {
                st.push_back(x);
            } else {
                st.push_back(-x);
            }
            op = (op + 1) % 4;
        }

        int ans = 0;
        for (int x : st) ans += x;
        return ans;
    }
};
