class Solution {
public:
    vector<int> numSmallerByFrequency(vector<string>& queries, vector<string>& words) {
        auto f = [](const string& s) {
            char smallest = 'z';
            int count = 0;

            for (char c : s) {
                if (c < smallest) {
                    smallest = c;
                    count = 1;
                } else if (c == smallest) {
                    count++;
                }
            }

            return count;
        };

        vector<int> wordFreq;
        for (const string& word : words) {
            wordFreq.push_back(f(word));
        }

        sort(wordFreq.begin(), wordFreq.end());

        vector<int> answer;
        for (const string& query : queries) {
            int qFreq = f(query);
            auto it = upper_bound(wordFreq.begin(), wordFreq.end(), qFreq);
            answer.push_back(wordFreq.end() - it);
        }

        return answer;
    }
};
