class Solution {
public:
    bool canCross(vector<int>& stones) {
        int n = stones.size();
        vector<vector<char>> dp(n, vector<char>(n + 2, 0));
        dp[0][0] = 1;

        for (int i = 1; i < n; ++i) {
            for (int j = i - 1; j >= 0; --j) {
                long long gapLL = (long long)stones[i] - stones[j];
                if (gapLL > n) break;

                int gap = (int)gapLL;
                if (dp[j][gap - 1] || dp[j][gap] || dp[j][gap + 1]) {
                    if (i == n - 1) return true;
                    dp[i][gap] = 1;
                }
            }
        }

        return false;
    }
};
