class Solution {
public:
    int maximumANDSum(vector<int>& nums, int numSlots) {
        int n = nums.size();

        vector<int> pow3(numSlots + 1, 1);
        for (int i = 1; i <= numSlots; i++) {
            pow3[i] = pow3[i - 1] * 3;
        }

        int totalStates = pow3[numSlots];
        vector<int> dp(totalStates, -1);
        dp[0] = 0;

        int ans = 0;

        for (int mask = 0; mask < totalStates; mask++) {
            if (dp[mask] == -1) continue;

            int used = 0;
            for (int i = 0; i < numSlots; i++) {
                used += (mask / pow3[i]) % 3;
            }

            if (used == n) {
                ans = max(ans, dp[mask]);
                continue;
            }

            for (int slot = 0; slot < numSlots; slot++) {
                int count = (mask / pow3[slot]) % 3;
                if (count < 2) {
                    int newMask = mask + pow3[slot];
                    int value = nums[used] & (slot + 1);
                    dp[newMask] = max(dp[newMask], dp[mask] + value);
                }
            }
        }

        return ans;
    }
};
