public:
    int maxEqualFreq(vector<int>& nums) {
        int n = nums.size();
        vector<int> count(100001, 0);
        vector<int> freq(n + 2, 0);

        int maxFreq = 0;
        int ans = 0;

        for (int i = 0; i < n; i++) {
            int x = nums[i];
            int oldFreq = count[x];

            if (oldFreq > 0) {
                freq[oldFreq]--;
            }

            count[x]++;
            int newFreq = count[x];
            freq[newFreq]++;
            maxFreq = max(maxFreq, newFreq);

            int len = i + 1;

            if (maxFreq == 1 ||
                maxFreq * freq[maxFreq] + 1 == len ||
                (maxFreq - 1) * (freq[maxFreq - 1] + 1) + 1 == len) {
                ans = len;
            }
        }

        return ans;
    }
};
