#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    long long maxRunTime(int n, vector<int>& batteries) {
        long long total = 0;
        for (int b : batteries) total += b;

        long long left = 0, right = total / n;

        while (left < right) {
            long long mid = left + (right - left + 1) / 2;
            long long available = 0;
            long long need = mid * n;

            for (int b : batteries) {
                available += min<long long>(b, mid);
                if (available >= need) break;
            }

            if (available >= need) {
                left = mid;
            } else {
                right = mid - 1;
            }
        }

        return left;
    }
};
