class Solution {
public:
    int maxStudents(vector<vector<char>>& seats) {
        int m = seats.size(), n = seats[0].size();
        int totalMasks = 1 << n;

        vector<int> good(m, 0);
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (seats[i][j] == '.') {
                    good[i] |= (1 << j);
                }
            }
        }

        vector<int> validMasks;
        vector<int> countBits(totalMasks, 0);

        for (int mask = 0; mask < totalMasks; mask++) {
            countBits[mask] = __builtin_popcount(mask);
            if ((mask & (mask << 1)) == 0) {
                validMasks.push_back(mask);
            }
        }

        vector<int> dp(totalMasks, -1);
        dp[0] = 0;

        for (int i = 0; i < m; i++) {
            vector<int> ndp(totalMasks, -1);

            for (int mask : validMasks) {
                if ((mask & ~good[i]) != 0) continue;

                for (int prev = 0; prev < totalMasks; prev++) {
                    if (dp[prev] == -1) continue;

                    if ((mask & (prev << 1)) == 0 && (mask & (prev >> 1)) == 0) {
                        ndp[mask] = max(ndp[mask], dp[prev] + countBits[mask]);
                    }
                }
            }

            dp = ndp;
        }

        return *max_element(dp.begin(), dp.end());
    }
};
