class Solution {
public:
    int minMalwareSpread(vector<vector<int>>& graph, vector<int>& initial) {
        int n = graph.size();
        sort(initial.begin(), initial.end());

        int answer = initial[0];
        int bestInfected = n + 1;

        for (int removed : initial) {
            vector<int> infected(n, 0);
            queue<int> q;

            infected[removed] = 1;
            int count = 0;

            for (int node : initial) {
                if (node == removed) continue;
                infected[node] = 1;
                q.push(node);
                count++;
            }

            while (!q.empty()) {
                int u = q.front();
                q.pop();

                for (int v = 0; v < n; v++) {
                    if (graph[u][v] == 1 && !infected[v]) {
                        infected[v] = 1;
                        q.push(v);
                        count++;
                    }
                }
            }

            if (count < bestInfected) {
                bestInfected = count;
                answer = removed;
            }
        }

        return answer;
    }
};
