        int totalMasks = 1 << m;
        vector<int> dp(totalMasks, -1);
        dp[0] = 0;

        for (int mask = 0; mask < totalMasks; mask++) {
            int studentIdx = __builtin_popcount(mask);
            if (studentIdx >= m) continue;

            for (int mentorIdx = 0; mentorIdx < m; mentorIdx++) {
                if ((mask & (1 << mentorIdx)) == 0) {
                    int nextMask = mask | (1 << mentorIdx);
                    dp[nextMask] = max(dp[nextMask], dp[mask] + score[studentIdx][mentorIdx]);
                }
            }
        }

        return dp[totalMasks - 1];
    }
};
