class Solution {
public:
    int maxSizeSlices(vector<int>& slices) {
        int m = slices.size();
        int k = m / 3;

        auto solve = [&](int start, int end) {
            int len = end - start + 1;
            const int NEG = -1000000000;
            vector<vector<int>> dp(len + 1, vector<int>(k + 1, NEG));
            dp[0][0] = 0;

            for (int i = 1; i <= len; i++) {
                dp[i][0] = 0;
                for (int j = 1; j <= k; j++) {
                    dp[i][j] = dp[i - 1][j];

                    int prev = NEG;
                    if (i >= 2) {
                        prev = dp[i - 2][j - 1];
                    } else if (j == 1) {
                        prev = 0;
                    }

                    if (prev != NEG) {
                        dp[i][j] = max(dp[i][j], prev + slices[start + i - 1]);
                    }
                }
            }

            return dp[len][k];
        };

        return max(solve(0, m - 2), solve(1, m - 1));
    }
};
