class Solution {
public:
    int minSessions(vector<int>& tasks, int sessionTime) {
        int n = tasks.size();
        int totalMasks = 1 << n;
        const int INF = 1e9;

        vector<pair<int, int>> dp(totalMasks, {INF, INF});
        dp[0] = {1, 0};

        for (int mask = 0; mask < totalMasks; mask++) {
            auto [sessions, used] = dp[mask];

            for (int i = 0; i < n; i++) {
                if (mask & (1 << i)) continue;

                int nextMask = mask | (1 << i);
                pair<int, int> candidate;

                if (used + tasks[i] <= sessionTime) {
                    candidate = {sessions, used + tasks[i]};
                } else {
                    candidate = {sessions + 1, tasks[i]};
                }

                if (candidate < dp[nextMask]) {
                    dp[nextMask] = candidate;
                }
            }
        }

        return dp[totalMasks - 1].first;
    }
};
