class Solution {
public:
    int numTriplets(vector<int>& nums1, vector<int>& nums2) {
        auto countTriplets = [](vector<int>& squaredNums, vector<int>& productNums) -> long long {
            unordered_map<long long, int> productCount;
            int n = productNums.size();

            for (int j = 0; j < n; ++j) {
                for (int k = j + 1; k < n; ++k) {
                    long long product = 1LL * productNums[j] * productNums[k];
                    productCount[product]++;
                }
            }

            long long result = 0;
            for (int num : squaredNums) {
                long long square = 1LL * num * num;
                if (productCount.count(square)) {
                    result += productCount[square];
                }
            }

            return result;
        };

        long long answer = countTriplets(nums1, nums2) + countTriplets(nums2, nums1);
        return (int)answer;
    }
};
