class Solution {
public:
    vector<double> medianSlidingWindow(vector<int>& nums, int k) {
        multiset<int> low, high;

        auto rebalance = [&]() {
            while (low.size() > high.size() + 1) {
                auto it = prev(low.end());
                high.insert(*it);
                low.erase(it);
            }
            while (low.size() < high.size()) {
                auto it = high.begin();
                low.insert(*it);
                high.erase(it);
            }
        };

        auto add = [&](int x) {
            if (low.empty() || x <= *prev(low.end())) {
                low.insert(x);
            } else {
                high.insert(x);
            }
            rebalance();
        };

        auto remove = [&](int x) {
            auto it = low.find(x);
            if (it != low.end()) {
                low.erase(it);
            } else {
                it = high.find(x);
                high.erase(it);
            }
            rebalance();
        };

        auto getMedian = [&]() -> double {
            if (k % 2 == 1) {
                return (double)*prev(low.end());
            }
            return ((double)*prev(low.end()) + (double)*high.begin()) / 2.0;
        };

        vector<double> ans;

        for (int i = 0; i < k; ++i) {
            add(nums[i]);
        }

        ans.push_back(getMedian());

        for (int i = k; i < nums.size(); ++i) {
            add(nums[i]);
            remove(nums[i - k]);
            ans.push_back(getMedian());
        }

        return ans;
    }
};
