using namespace std;

class Solution {
public:
    int splitArray(vector<int>& nums, int k) {
        long long left = 0, right = 0;

        for (int num : nums) {
            left = max(left, (long long)num);
            right += num;
        }

        auto canSplit = [&](long long maxSum) {
            int subarrays = 1;
            long long currentSum = 0;

            for (int num : nums) {
                if (currentSum + num > maxSum) {
                    subarrays++;
                    currentSum = num;
                } else {
                    currentSum += num;
                }
