class Solution {
    vector<int> parent, rankv;
    int components;

    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    void unite(int a, int b) {
        int pa = find(a), pb = find(b);
        if (pa == pb) return;

        if (rankv[pa] < rankv[pb]) swap(pa, pb);
        parent[pb] = pa;
        if (rankv[pa] == rankv[pb]) rankv[pa]++;
        components--;
    }

public:
    int regionsBySlashes(vector<string>& grid) {
        int n = grid.size();
        int total = n * n * 4;

        parent.resize(total);
        rankv.assign(total, 0);
        components = total;

        for (int i = 0; i < total; i++) {
            parent[i] = i;
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int base = (i * n + j) * 4;
                char c = grid[i][j];

                if (c == ' ') {
                    unite(base + 0, base + 1);
                    unite(base + 1, base + 2);
                    unite(base + 2, base + 3);
                } else if (c == '/') {
                    unite(base + 0, base + 3);
                    unite(base + 1, base + 2);
                } else {
                    unite(base + 0, base + 1);
                    unite(base + 2, base + 3);
                }

                if (i + 1 < n) {
                    int down = ((i + 1) * n + j) * 4;
                    unite(base + 2, down + 0);
                }

                if (j + 1 < n) {
                    int right = (i * n + j + 1) * 4;
                    unite(base + 1, right + 3);
                }
            }
        }

        return components;
    }
};
