class StreamChecker {
    struct Node {
        int child[26];
        bool isWord;

        Node() {
            for (int i = 0; i < 26; ++i) child[i] = -1;
            isWord = false;
        }
    };

    vector<Node> trie;
    string stream;
    int maxLen;

public:
    StreamChecker(vector<string>& words) {
        trie.push_back(Node());
        maxLen = 0;

        for (const string& word : words) {
            maxLen = max(maxLen, (int)word.size());
            int node = 0;

            for (int i = (int)word.size() - 1; i >= 0; --i) {
                int c = word[i] - 'a';

                if (trie[node].child[c] == -1) {
                    trie[node].child[c] = trie.size();
                    trie.push_back(Node());
                }

                node = trie[node].child[c];
            }

            trie[node].isWord = true;
        }
    }

    bool query(char letter) {
        stream.push_back(letter);

        if ((int)stream.size() > maxLen) {
            stream.erase(stream.begin());
        }

        int node = 0;

        for (int i = (int)stream.size() - 1; i >= 0; --i) {
            int c = stream[i] - 'a';

            if (trie[node].child[c] == -1) {
                return false;
            }

            node = trie[node].child[c];

            if (trie[node].isWord) {
                return true;
            }
        }

        return false;
    }
};
